const text = (value) => typeof value === 'string' ? value.trim() : '';
const sessionId = text($json.sessionId);
const currentUserInstruction = text($json.currentUserInstruction);
const searchMode = text($json.searchMode || 'people').toLowerCase();
const industry = text($json.industry);
const location = text($json.location);
const roleTitle = text($json.roleTitle);
const keywords = text($json.keywords);
const companyHeadcount = text($json.companyHeadcount);
const requestedLimit = Number($json.maxResults || 10);
const maxResults = Number.isInteger(requestedLimit) ? requestedLimit : NaN;
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const splitTerms = (value) => value.split(/[,;/|]+/).map((part) => part.trim()).filter(Boolean);
const headcountBounds = (value) => {
  if (!value) return null;
  const compact = value.replace(/[\s,]/g, '').replace(/[–—]/g, '-');
  let match = /^(\d+)-(\d+)$/.exec(compact);
  if (match) {
    const lower = Number(match[1]);
    const upper = Number(match[2]);
    return lower <= upper ? [lower, upper] : null;
  }
  match = /^(\d+)\+$/.exec(compact);
  if (match) return [Number(match[1]), null];
  if (/^\d+$/.test(compact)) return [Number(compact), Number(compact)];
  return null;
};
const group = (op, conditions) => conditions.length === 1 ? conditions[0] : ({ op, conditions });
const headcountConditions = (field, value) => {
  const bounds = headcountBounds(value);
  if (!bounds) return [];
  const conditions = [{ field, type: '=>', value: bounds[0] }];
  if (bounds[1] !== null) conditions.push({ field, type: '=<', value: bounds[1] });
  return conditions;
};

let error = null;
if (!uuidPattern.test(sessionId)) {
  error = { code: 'INVALID_SESSION', message: 'The research request needs a valid conversation session.' };
} else if (!['people', 'companies'].includes(searchMode)) {
  error = { code: 'INVALID_SEARCH_MODE', message: 'searchMode must be people or companies.' };
} else if (!industry || industry.length > 200) {
  error = { code: 'INVALID_INDUSTRY', message: 'Industry is required and must be 200 characters or fewer.' };
} else if (splitTerms(industry).length === 0) {
  error = { code: 'INVALID_INDUSTRY', message: 'Industry must contain at least one searchable term.' };
} else if (!location || location.length > 200) {
  error = { code: 'INVALID_LOCATION', message: 'Location is required and must be 200 characters or fewer.' };
} else if (searchMode === 'people' && (!roleTitle || roleTitle.length > 160)) {
  error = { code: 'INVALID_ROLE_TITLE', message: 'People mode requires a role title of 160 characters or fewer.' };
} else if (keywords.length > 500) {
  error = { code: 'INVALID_KEYWORDS', message: 'Keywords must be 500 characters or fewer.' };
} else if (!Number.isInteger(maxResults) || maxResults < 1 || maxResults > 25) {
  error = { code: 'INVALID_LIMIT', message: 'maxResults must be a whole number between 1 and 25.' };
} else if (companyHeadcount && !headcountBounds(companyHeadcount)) {
  error = { code: 'INVALID_HEADCOUNT', message: 'Company headcount must be a number, a range such as 51-200, or a value such as 1001+.' };
}

const criteria = { searchMode, industry, location, roleTitle: roleTitle || null, keywords: keywords || null, companyHeadcount: companyHeadcount || null, maxResults };
const estimatedMaxCredits = Number.isInteger(maxResults) ? Number((maxResults * 0.03).toFixed(2)) : 0;
const approvalScope = [searchMode, industry, location, roleTitle, keywords, companyHeadcount, String(maxResults)].join('\u001f');
let approvalHash = 2166136261;
for (let index = 0; index < approvalScope.length; index += 1) {
  approvalHash = Math.imul(approvalHash ^ approvalScope.charCodeAt(index), 16777619) >>> 0;
}
const approvalCode = approvalHash.toString(16).toUpperCase().padStart(8, '0');
const approvalPhrase = `APPROVE CRUSTDATA ${estimatedMaxCredits.toFixed(2)} CREDITS ${approvalCode}`;
let endpoint = '';
let requestBody = null;

if (!error) {
  const industryTerms = splitTerms(industry);
  const conditions = [];
  if (searchMode === 'people') {
    conditions.push(group('or', industryTerms.map((term) => ({
      field: 'experience.employment_details.current.company_professional_network_industry',
      type: '(.)',
      value: term
    }))));
    conditions.push({ field: 'basic_profile.location.full_location', type: '(.)', value: location });
    conditions.push({ field: 'experience.employment_details.current.title', type: '(.)', value: roleTitle });
    conditions.push(...headcountConditions('experience.employment_details.current.company_headcount_latest', companyHeadcount));
    requestBody = {
      filters: { op: 'and', conditions },
      mode: 'exact',
      fields: [
        'fit',
        'metadata.updated_at',
        'basic_profile',
        'experience.employment_details.current',
        'social_handles.professional_network_identifier.profile_url'
      ],
      limit: maxResults
    };
    if (keywords) {
      requestBody.search = { query: `${roleTitle}. ${keywords}`, mode: 'hybrid' };
    } else {
      requestBody.sorts = [{ field: 'metadata.updated_at', order: 'desc' }];
    }
    endpoint = 'https://api.crustdata.com/person/search';
  } else {
    const industryFields = [
      'taxonomy.professional_network_industry',
      'taxonomy.categories',
      'taxonomy.professional_network_specialities'
    ];
    conditions.push(group('or', industryTerms.flatMap((term) =>
      industryFields.map((field) => ({ field, type: '(.)', value: term }))
    )));
    conditions.push({ field: 'locations.headquarters', type: '(.)', value: location });
    if (keywords) {
      conditions.push(group('or', [
        'basic_info.name',
        'taxonomy.categories',
        'taxonomy.professional_network_specialities'
      ].map((field) => ({ field, type: '(.)', value: keywords }))));
    }
    conditions.push(...headcountConditions('headcount.total', companyHeadcount));
    requestBody = {
      filters: { op: 'and', conditions },
      fields: [
        'metadata.updated_at',
        'basic_info.name',
        'basic_info.website',
        'basic_info.professional_network_url',
        'basic_info.company_type',
        'headcount.total',
        'locations.country',
        'locations.state',
        'locations.city',
        'locations.headquarters',
        'taxonomy.professional_network_industry',
        'taxonomy.categories',
        'taxonomy.professional_network_specialities'
      ],
      sorts: [{ column: 'headcount.total', order: 'desc' }],
      limit: maxResults
    };
    endpoint = 'https://api.crustdata.com/company/search';
  }
}

return {
  json: {
    valid: error === null,
    approved: error === null && currentUserInstruction === approvalPhrase,
    sessionId,
    criteria,
    estimatedMaxCredits,
    approvalPhrase,
    endpoint,
    requestBody,
    ...(error ? { response: { ok: false, approvalRequired: false, error } } : {})
  }
};

if ($json.valid !== true) return { json: $json };
return {
  json: {
    ...$json,
    response: {
      ok: true,
      approvalRequired: true,
      message: 'No provider request was made and no credits were spent. Send the exact approval phrase as a separate message to run this bounded search.',
      approvalPhrase: $json.approvalPhrase,
      estimatedMaxCredits: $json.estimatedMaxCredits,
      estimatedPricing: 'Crustdata indexed search is currently documented at 0.03 credits per returned result; verify current account pricing.',
      searchCriteria: $json.criteria,
      coverage: 'Preview only; no research results yet'
    }
  }
};

const input = $('Validate and Build Search').first().json;
const full = $json && typeof $json === 'object' ? $json : {};
const statusCode = Number(full.statusCode ?? 200);
const body = full.body && typeof full.body === 'object' ? full.body : full;
const headers = full.headers && typeof full.headers === 'object' ? full.headers : {};
const safeProviderError = () => {
  if (statusCode === 401) return { code: 'CRUSTDATA_CREDENTIAL_INVALID', message: 'Crustdata rejected the credential. Recreate CRUSTDATA_API_KEY as Bearer Auth and paste only the raw cd_... key.' };
  if (statusCode === 403) return { code: 'CRUSTDATA_ACCESS_DENIED', message: 'The Crustdata account lacks permission or sufficient credits for this indexed search.' };
  if (statusCode === 429) return { code: 'CRUSTDATA_RATE_LIMITED', message: 'Crustdata rate-limited the request. No automatic retry was attempted.' };
  if (statusCode >= 400) return { code: 'CRUSTDATA_REQUEST_FAILED', message: 'Crustdata could not run the bounded search. Check the filters and account endpoint permissions.' };
  if (body.error) return { code: 'CRUSTDATA_REQUEST_FAILED', message: 'Crustdata returned an error for the bounded search.' };
  return null;
};
const providerError = safeProviderError();
if (providerError) {
  return {
    json: {
      ...input,
      response: {
        ok: false,
        approvalRequired: false,
        searchCriteria: input.criteria,
        estimatedMaxCredits: input.estimatedMaxCredits,
        error: providerError
      }
    }
  };
}

const text = (value) => typeof value === 'string' ? value.trim() : '';
const nested = (value, path) => path.reduce((current, key) =>
  current && typeof current === 'object' ? current[key] : undefined, value);
const firstText = (...values) => {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (Array.isArray(value)) {
      const joined = value.filter((item) => typeof item === 'string' && item.trim()).join(', ');
      if (joined) return joined;
    }
    if (value && typeof value === 'object') {
      for (const key of ['raw', 'full_location', 'name', 'value', 'url']) {
        if (typeof value[key] === 'string' && value[key].trim()) return value[key].trim();
      }
    }
  }
  return '';
};
const canonicalLinkedIn = (value, kind) => {
  let raw = text(value);
  if (!raw) return null;
  if (!/^https?:\/\//i.test(raw)) raw = `https://${raw}`;
  try {
    const parsed = new URL(raw);
    const host = parsed.hostname.toLowerCase();
    if (host !== 'linkedin.com' && !host.endsWith('.linkedin.com')) return null;
    const prefix = kind === 'person' ? '/in/' : '/company/';
    const path = parsed.pathname.replace(/\/+/, '/');
    if (!path.toLowerCase().startsWith(prefix)) return null;
    const slug = path.slice(prefix.length).replace(/^\/+|\/+$/g, '');
    if (!slug || slug.includes('/') || !/^[A-Za-z0-9%_.~-]+$/.test(slug)) return null;
    return `https://www.linkedin.com${prefix}${slug}`;
  } catch {
    return null;
  }
};
const currentRole = (profile) => {
  const current = nested(profile, ['experience', 'employment_details', 'current']);
  if (Array.isArray(current)) return current.find((item) => item && typeof item === 'object') || {};
  return current && typeof current === 'object' ? current : {};
};
const hardFilters = [
  'industry',
  'location',
  ...(input.criteria.searchMode === 'people' ? ['current role title'] : []),
  ...(input.criteria.keywords ? ['keywords'] : []),
  ...(input.criteria.companyHeadcount ? ['company headcount'] : [])
];

const excludedResults = [];
const qualified = [];
const seen = new Set();
const sourceItems = input.criteria.searchMode === 'people'
  ? (Array.isArray(body.profiles) ? body.profiles : [])
  : (Array.isArray(body.companies) ? body.companies : []);

for (const source of sourceItems) {
  if (!source || typeof source !== 'object') continue;
  if (input.criteria.searchMode === 'people') {
    const basic = source.basic_profile && typeof source.basic_profile === 'object' ? source.basic_profile : {};
    const role = currentRole(source);
    const profileUrl = canonicalLinkedIn(firstText(
      source.profile_url,
      source.linkedin_url,
      nested(source, ['social_handles', 'professional_network_identifier', 'profile_url'])
    ), 'person');
    const companyUrl = canonicalLinkedIn(firstText(
      role.company_professional_network_profile_url,
      role.company_linkedin_profile_url
    ), 'company');
    const item = {
      name: firstText(source.name, basic.name) || null,
      currentTitle: firstText(source.current_title, basic.current_title, role.title) || null,
      company: firstText(source.company, source.current_company, role.name, role.company_name) || null,
      location: firstText(source.location, basic.location) || null,
      profileUrl,
      companyProfileUrl: companyUrl,
      headline: firstText(source.headline, basic.headline) || null,
      industry: firstText(source.industry, role.company_professional_network_industry, role.company_industries) || null,
      companyHeadcount: role.company_headcount_latest ?? firstText(role.company_headcount_range) ?? null,
      fit: firstText(source.fit) || null,
      lastUpdated: firstText(nested(source, ['metadata', 'updated_at'])) || null,
      criteriaStatus: profileUrl ? 'qualified' : 'excluded',
      matchEvidence: profileUrl ? hardFilters.map((field) => `Crustdata hard filter: ${field}`) : [],
      unverifiedCriteria: [
        ...(!firstText(source.location, basic.location) ? ['returned location field'] : []),
        ...(!firstText(role.company_professional_network_industry, role.company_industries) ? ['returned industry field'] : [])
      ],
      conflictingCriteria: profileUrl ? [] : ['missing valid public LinkedIn person URL']
    };
    if (!profileUrl) {
      excludedResults.push(item);
    } else if (!seen.has(profileUrl)) {
      seen.add(profileUrl);
      qualified.push(item);
    }
  } else {
    const basic = source.basic_info && typeof source.basic_info === 'object' ? source.basic_info : {};
    const locations = source.locations && typeof source.locations === 'object' ? source.locations : {};
    const taxonomy = source.taxonomy && typeof source.taxonomy === 'object' ? source.taxonomy : {};
    const headcount = source.headcount && typeof source.headcount === 'object' ? source.headcount : {};
    const companyUrl = canonicalLinkedIn(firstText(
      source.company_profile_url,
      source.linkedin_url,
      basic.professional_network_url,
      nested(source, ['social_profiles', 'professional_network'])
    ), 'company');
    const item = {
      name: firstText(source.name, basic.name) || null,
      companyProfileUrl: companyUrl,
      website: firstText(basic.website) || null,
      companyType: firstText(basic.company_type) || null,
      industry: firstText(taxonomy.professional_network_industry, taxonomy.categories, taxonomy.professional_network_specialities) || null,
      headquarters: firstText(locations.headquarters, [locations.city, locations.state, locations.country].filter(Boolean)) || null,
      companyHeadcount: Number.isFinite(Number(headcount.total)) ? Number(headcount.total) : null,
      categories: Array.isArray(taxonomy.categories) ? taxonomy.categories : [],
      specialities: Array.isArray(taxonomy.professional_network_specialities) ? taxonomy.professional_network_specialities : [],
      lastUpdated: firstText(nested(source, ['metadata', 'updated_at'])) || null,
      criteriaStatus: companyUrl ? 'qualified' : 'excluded',
      matchEvidence: companyUrl ? hardFilters.map((field) => `Crustdata hard filter: ${field}`) : [],
      unverifiedCriteria: [
        ...(!firstText(locations.headquarters, locations.city, locations.state, locations.country) ? ['returned headquarters field'] : []),
        ...(!firstText(taxonomy.professional_network_industry, taxonomy.categories, taxonomy.professional_network_specialities) ? ['returned industry field'] : [])
      ],
      conflictingCriteria: companyUrl ? [] : ['missing valid public LinkedIn company URL']
    };
    if (!companyUrl) {
      excludedResults.push(item);
    } else if (!seen.has(companyUrl)) {
      seen.add(companyUrl);
      qualified.push(item);
    }
  }
}

const rawCredits = headers['x-credits-used'] ?? headers['X-Credits-Used'] ?? body.credits_used ?? body.credits_cost;
const parsedCredits = Number(rawCredits);
const creditsUsed = Number.isFinite(parsedCredits)
  ? parsedCredits
  : Number((sourceItems.length * 0.03).toFixed(2));
const employerMap = new Map();
if (input.criteria.searchMode === 'people') {
  for (const profile of qualified) {
    if (profile.companyProfileUrl && !employerMap.has(profile.companyProfileUrl)) {
      employerMap.set(profile.companyProfileUrl, { company: profile.company, companyProfileUrl: profile.companyProfileUrl });
    }
  }
}
const companies = input.criteria.searchMode === 'people' ? [...employerMap.values()] : qualified;
return {
  json: {
    ...input,
    response: {
      ok: true,
      approvalRequired: false,
      searchMode: input.criteria.searchMode,
      searchCriteria: input.criteria,
      profiles: input.criteria.searchMode === 'people' ? qualified : [],
      profileUrls: input.criteria.searchMode === 'people' ? qualified.map((item) => item.profileUrl) : [],
      companies,
      companyUrls: companies.map((item) => item.companyProfileUrl),
      excludedResults,
      totalCount: qualified.length,
      providerTotalCount: Number.isFinite(Number(body.total_count)) ? Number(body.total_count) : null,
      creditsUsed,
      estimatedMaxCredits: input.estimatedMaxCredits,
      coverage: 'Bounded indexed Crustdata result; not exhaustive',
      safety: 'Public professional fields only; no personal contact data requested'
    }
  }
};

const response = $json.response;
const summary = {
  ok: response?.ok === true,
  approvalRequired: response?.approvalRequired === true,
  searchMode: $json.criteria?.searchMode ?? null,
  returnedCount: Number(response?.totalCount ?? 0),
  creditsUsed: response?.creditsUsed ?? 0,
  estimatedMaxCredits: $json.estimatedMaxCredits ?? 0,
  errorCode: response?.error?.code ?? null
};
return {
  json: {
    occurredAt: new Date().toISOString(),
    sessionId: String($json.sessionId ?? ''),
    requestId: '',
    toolName: 'search_linkedin_prospects',
    proposedInput: JSON.stringify($json.criteria ?? {}),
    result: JSON.stringify(summary),
    error: response?.ok === false ? String(response.error?.message ?? 'Research tool failed') : '',
    response
  }
};

const prepared = $('Prepare Research Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The research result could not be written to the local audit table.';
}
return { json: response };
